// Exact author finite interval checker for frozen T6 p17 valuation-one order8.
// Input generated by T6_P17_Q8_INTERVAL_GENERATOR_20261123.py.
// This version correctly propagates ORIGINAL affine coefficients (c+n), not
// the conditional orthogonalized GS center. Interval test only rejects when
// its exact lower energy bound exceeds the necessary weighted sphere bound.
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include <chrono>
using namespace std;
constexpr int N=16;constexpr int CAP=2331;
using i128=__int128_t;
int64_t SCALE;int Q;int DLO[16];int64_t MULO[16][16],MUHI[16][16];
string data_dir=".";
void readconstants(){
 ifstream f(data_dir+"/t6q8_interval_constants.txt");
 if(!f)throw runtime_error("missing generated constants");
 f>>Q>>SCALE;
 for(int i=0;i<16;i++)f>>DLO[i];
 for(int i=0;i<16;i++)for(int j=0;j<16;j++)f>>MULO[i][j];
 for(int i=0;i<16;i++)for(int j=0;j<16;j++)f>>MUHI[i][j];
 if(Q!=24137569 || SCALE!=(1LL<<32))throw runtime_error("unexpected precision");
 if(*min_element(DLO,DLO+16)<=3354730)throw runtime_error("incomplete nearest-integer enumeration");
}
struct State{int cost;uint64_t lo=0,hi=0;array<int,N> c;vector<int> atoms;};
vector<State> readstates(int ord){
 ifstream f(data_dir+"/t6q8_states"+to_string(ord)+".txt");
 if(!f)throw runtime_error("missing state file");
 int n;f>>n;vector<State> v(n);
 for(auto &s:v){int k;f>>s.cost>>k;
  for(int j=0;j<k;j++){int a;f>>a;s.atoms.push_back(a);if(a<64)s.lo|=1ULL<<a;else s.hi|=1ULL<<(a-64);}
  for(int j=0;j<N;j++)f>>s.c[j];
 }
 return v;
}
int64_t floor_div(i128 a,int64_t b){if(a>=0)return int64_t(a/b);else return -int64_t((-a+b-1)/b);}
int64_t ceil_div(i128 a,int64_t b){return -floor_div(-a,b);}
int64_t cLo[16],cHi[16],zLo[16],zHi[16];
uint64_t nodes=0,loose_leaves=0;
uint64_t raw=0,shared=0,primitive=0;
vector<string> samples;
int currentLeft=0,currentRight=0;
inline void calcProduct(int64_t a,int64_t b,int64_t c,int64_t d,int64_t &outLo,int64_t&outHi){
 i128 p[4]={(i128)a*c,(i128)a*d,(i128)b*c,(i128)b*d};
 i128 low=*min_element(p,p+4),high=*max_element(p,p+4);
 outLo=floor_div(low,SCALE);outHi=ceil_div(high,SCALE);
}
void visit(int i,i128 normLower,i128 limit){
 if(i<0){loose_leaves++;if(samples.size()<10)samples.push_back(to_string(currentLeft)+":"+to_string(currentRight));return;}
 nodes++;
 int64_t low=cLo[i],hi=cHi[i];
 for(int j=i+1;j<N;j++){
  int64_t a,b;calcProduct(zLo[j],zHi[j],MULO[j][i],MUHI[j][i],a,b);
  low+=a;hi+=b;
 }
 int64_t nmin=floor_div(-(i128)hi,SCALE)-1;
 int64_t nmax=floor_div(-(i128)low,SCALE)+2;
 for(int64_t n=nmin;n<=nmax;n++){
  int64_t a=low+n*SCALE,b=hi+n*SCALE;
  int64_t m=(a<=0&&b>=0)?0:min(abs(a),abs(b));
  i128 next=normLower+(i128)DLO[i]*m*m;
  if(next<=limit){
    // For lower coordinates use the ORIGINAL c_i+n_i, not the
    // conditional GS coefficient a..b (a bug in discarded draft).
    zLo[i]=cLo[i]+n*SCALE;
    zHi[i]=cHi[i]+n*SCALE;
    visit(i-1,next,limit);
  }
 }
}
int main(int argc,char**argv){
 if(argc>=2)data_dir=argv[1];
 int orderA=2,orderB=6;
 if(argc>=3)orderA=atoi(argv[2]);
 if(argc>=4)orderB=atoi(argv[3]);
 readconstants();
 auto left=readstates(orderA),right=readstates(orderB);
 int begin=0,end=left.size();
 if(argc>=5)begin=atoi(argv[4]);
 if(argc>=6)end=atoi(argv[5]);
 auto started=chrono::steady_clock::now();
 for(int li=begin;li<end;li++){
  auto &p=left[li];
  for(int ri=0;ri<(int)right.size();ri++){
   auto &n=right[ri];
   if(orderA==orderB && ri<=li)continue;
   raw++;
   if((p.lo&n.lo)||(p.hi&n.hi)){shared++;continue;}
   primitive++;
   currentLeft=li;currentRight=ri;
   int64_t radius=(int64_t)(CAP-p.cost)*(CAP-p.cost)+(int64_t)(CAP-n.cost)*(CAP-n.cost);
   i128 limit=(i128)radius*SCALE*SCALE;
   for(int i=0;i<N;i++){
    int t=p.c[i]-n.c[i];
    if(t<0)t+=Q;
    i128 v=(i128)t*SCALE;
    cLo[i]=int64_t(v/Q);
    cHi[i]=cLo[i]+(v%Q!=0);
   }
   visit(15,0,limit);
  }
  if((li+1)%16==0)
   cerr<<"PROGRESS left="<<li+1<<" primitive="<<primitive
       <<" nodes="<<nodes<<" leaves="<<loose_leaves
       <<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-started).count()<<"\n";
 }
 cout<<"{\"orders\":["<<orderA<<","<<orderB<<"],\"range\":["<<begin<<","<<end
     <<"],\"raw\":"<<raw<<",\"shared\":"<<shared<<",\"primitive\":"<<primitive
     <<",\"interval_nodes\":"<<nodes<<",\"interval_sphere_leaves\":"<<loose_leaves
     <<",\"sample_leaves\":[";
 for(int i=0;i<(int)samples.size();i++){
  if(i)cout<<",";
  cout<<"\""<<samples[i]<<"\"";
 }
 cout<<"]}\n";
}
